questionvariables.text:
/* ALL tuples exclusively produce perfectly clean INTEGER intercepts and intersections to respect the 1-unit snap grid */
tuples : [
    [3, 2, 24, 1, 2, 16], /* Int: (4,6). M_int: (8,12). L_int: (16,8). */
    [2, 3, 18, 2, 1, 10], /* Int: (3,4). M_int: (9,6). L_int: (5,10). */
    [1, 1, 8, 2, 1, 12],  /* Int: (4,4). M_int: (8,8). L_int: (6,12). */
    [1, 2, 12, 3, 2, 24]  /* Int: (6,3). M_int: (12,6). L_int: (8,12). */
];
tup : rand(tuples);
A : tup[1];
B : tup[2];
C : tup[3];
D : tup[4];
E : tup[5];
F : tup[6];

/* Target Inequalities */
ta1 : A*x + B*y <= C;
ta2 : D*x + E*y <= F;

/* Target Coordinates */
ta3 : [0, C/B];
ta4 : [C/A, 0];
ta5 : [0, F/E];
ta6 : [F/D, 0];

/* Region Marker Target - [1, 1] is mathematically guaranteed to be within the feasible region for all tuples */
ta7 : [1, 1];
ta7_wrong : [15, 15];

feedbackvariables.text:
/* Extract coordinates of the two blue points */
x1 : ans3[1];
y1 : ans3[2];
x2 : ans4[1];
y2 : ans4[2];

/* Extract coordinates of the two red points */
x3 : ans5[1];
y3 : ans5[2];
x4 : ans6[1];
y4 : ans6[2];

/* Extract coordinate of the green region marker */
rx : ans7[1];
ry : ans7[2];
